class UserOrdersResponse {
  UserOrdersResponse({
      this.message, 
      this.orders,});

  UserOrdersResponse.fromJson(dynamic json) {
    message = json['message'];
    if (json['orders'] != null) {
      orders = [];
      json['orders'].forEach((v) {
        orders?.add(UserOrders.fromJson(v));
      });
    }
  }
  String? message;
  List<UserOrders>? orders;

  Map<String, dynamic> toJson() {
    final map = <String, dynamic>{};
    map['message'] = message;
    if (orders != null) {
      map['orders'] = orders?.map((v) => v.toJson()).toList();
    }
    return map;
  }

  UserOrdersResponseEntity toUserOrderResponseEntity() {
    return UserOrdersResponseEntity(
        message: message,
        orders: orders
    );
  }



